//! Repository for PurchaseAgreement entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written blanket-agreement SQL (4-layer rule: services orchestrate, repos
//! hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<PurchaseAgreement, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use sqlx::{PgPool, Row};
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::PurchaseAgreement;

/// Table name for PurchaseAgreement entities
pub const TABLE_NAME: &str = "buying.purchase_agreements";

/// Repository for PurchaseAgreement entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct PurchaseAgreementRepository(
    backbone_orm::GenericCrudRepository<PurchaseAgreement, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for PurchaseAgreementRepository {
    type Target = backbone_orm::GenericCrudRepository<PurchaseAgreement, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl PurchaseAgreementRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a blanket-agreement header insert writes. `status` is not a field — the INSERT
/// hard-codes `'draft'`; `open` is reached through the confirm verb, which is also the ONLY writer
/// of the agreement's supplier prices.
pub struct NewAgreementRow<'a> {
    pub id: Uuid,
    pub agreement_number: &'a str,
    pub company_id: Uuid,
    pub supplier_id: Uuid,
    pub currency: &'a str,
    pub date_start: Option<chrono::NaiveDate>,
    pub date_end: Option<chrono::NaiveDate>,
    pub notes: Option<&'a str>,
}

/// An agreement's state + identity, as the agreement verbs gate on it. `draft_order_count` counts
/// live call-off POs in pre-confirmed states (`draft`/`sent`/`to_approve`) that still hang off the
/// agreement — the close/cancel refusal (a draft call-off would silently lose its price source).
pub struct AgreementStateRow {
    pub company_id: Uuid,
    pub supplier_id: Uuid,
    pub currency: String,
    pub status: String,
    pub draft_order_count: i64,
}

/// Hand-written PurchaseAgreement SQL. Lives here (not in the write service) per the module's
/// 4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL.
impl PurchaseAgreementRepository {
    /// Insert a blanket-agreement header as `draft`.
    ///
    /// Takes the CALLER'S connection so the header and its lines commit as one unit. The caller has
    /// already bound the company on it (`bind_company_on`) — don't re-bind here.
    pub async fn insert_agreement(
        &self,
        conn: &mut sqlx::PgConnection,
        a: &NewAgreementRow<'_>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO buying.purchase_agreements
                (id, agreement_number, agreement_kind, status, company_id, supplier_id, currency,
                 date_start, date_end, notes)
               VALUES ($1,$2,'blanket'::agreement_kind,'draft'::purchase_agreement_status,$3,$4,$5,$6,$7,$8)"#,
        )
        .bind(a.id).bind(a.agreement_number).bind(a.company_id).bind(a.supplier_id).bind(a.currency)
        .bind(a.date_start).bind(a.date_end).bind(a.notes)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Read an agreement's gate state. `Ok(None)` = not found (or another company's — the read
    /// rides the connection carrying the caller's `app.company_id`).
    pub async fn fetch_state(
        &self,
        pool: &PgPool,
        agreement_id: Uuid,
    ) -> Result<Option<AgreementStateRow>, sqlx::Error> {
        let row = company_scope::fetch_optional_row_scoped(
            pool,
            sqlx::query(
                r#"SELECT a.company_id, a.supplier_id, a.currency, a.status::text AS st,
                          (SELECT count(*) FROM buying.purchase_orders po
                            WHERE po.agreement_id = a.id
                              AND po.status IN ('draft','sent','to_approve')
                              AND (po.metadata->>'deleted_at') IS NULL) AS draft_order_count
                   FROM buying.purchase_agreements a
                   WHERE a.id=$1 AND (a.metadata->>'deleted_at') IS NULL"#,
            ).bind(agreement_id),
        )
        .await?;
        Ok(row.map(|r| AgreementStateRow {
            company_id: r.get("company_id"),
            supplier_id: r.get("supplier_id"),
            currency: r.get("currency"),
            status: r.get("st"),
            draft_order_count: r.get("draft_order_count"),
        }))
    }

    /// Flip the agreement's status, guarded on the allowed source states. `Ok(None)` = refused
    /// (wrong source state or absent). Takes the CALLER'S connection so the flip commits atomically
    /// with the verb's other writes (the confirm's price mint, the retire's price unlink); the
    /// caller has already bound the company on it.
    pub async fn transition(
        &self,
        conn: &mut sqlx::PgConnection,
        agreement_id: Uuid,
        to: &str,
        from: &[&str],
    ) -> Result<Option<Uuid>, sqlx::Error> {
        let from_list = from.iter().map(|s| format!("'{}'", s)).collect::<Vec<_>>().join(",");
        let sql = format!(
            r#"UPDATE buying.purchase_agreements SET status=$2::purchase_agreement_status
                WHERE id=$1 AND status = ANY(ARRAY[{from_list}]::purchase_agreement_status[])
                  AND (metadata->>'deleted_at') IS NULL
                RETURNING company_id"#,
            from_list = from_list,
        );
        let row = sqlx::query(&sql).bind(agreement_id).bind(to)
            .fetch_optional(conn).await?;
        Ok(row.map(|r| { let v: Uuid = r.get("company_id"); v }))
    }
}

backbone_core::impl_crud_repository!(PurchaseAgreementRepository, PurchaseAgreement, soft_delete);
